using System;
using EmberBastion;
class BurnDamageChecks {
 static void Near(double actual,double expected,string name){if(Math.Abs(actual-expected)>1e-6)throw new Exception(name+": expected "+expected+", got "+actual);}
 static Battle Setup(){var b=new Battle();if(!b.Place(0,0)||!b.Start())throw new Exception("setup");b.Units.Clear();b.Enemies.Add(new Enemy{Id=900,Kind=0,HP=1000,MaxHP=1000,Burn=2,Position=new Point(500,128)});b.Enemies.Add(new Enemy{Id=901,Kind=2,HP=1000,MaxHP=1000,Burn=2,Position=new Point(600,128)});b.Enemies.Add(new Enemy{Id=902,Kind=2,HP=1000,MaxHP=1000,Burn=2,Shield=2,Position=new Point(700,128)});return b;}
 static void Main(){try{var a=Setup();var copy=a.CopyCombat();for(int i=0;i<60;i++){a.Step(1.0/60);copy.Step(1.0/60);}Near(a.Enemies.Find(e=>e.Id==900).HP,992,"unarmored one second");Near(a.Enemies.Find(e=>e.Id==901).HP,999,"armored minimum per second");Near(a.Enemies.Find(e=>e.Id==902).HP,999.5,"shielded armored minimum per second");for(int k=900;k<=902;k++)Near(a.Enemies.Find(e=>e.Id==k).HP,copy.Enemies.Find(e=>e.Id==k).HP,"retry copy");var full=Setup();var duration=full.Enemies.Find(e=>e.Id==900);duration.Burn=3;for(int i=0;i<181;i++)full.Step(1.0/60);Near(duration.HP,976,"three second duration");var partial=Setup();var shortBurn=partial.Enemies.Find(e=>e.Id==900);shortBurn.Burn=1.0/120;var armorBurn=partial.Enemies.Find(e=>e.Id==901);armorBurn.Burn=1.0/120;partial.Step(1.0/60);Near(shortBurn.HP,1000-8.0/120,"fractional final tick");Near(armorBurn.HP,1000-1.0/120,"fractional armored final tick");Console.WriteLine("PASS burn damage, duration, fractional final tick, armor, shield and retry determinism");}catch(Exception e){Console.Error.WriteLine(e);Environment.Exit(1);}}
}
